  1	#pragma once
  2	
  3	// Remembered spools, a fork-owned concept OrcaSlicer does not have.
  4	//
  5	// Orca knows filament presets and one colour per extruder in the project
  6	// config. It has no idea that the same PLA+ preset in white and in black are
  7	// two physical reels a person swaps between. A spool is that pairing, named by
  8	// the person who owns it, remembered per printer.
  9	//
 10	// Machine facts are app-level, not project-level, so this lives beside the
 11	// application data rather than inside the 3mf: a project opened on another
 12	// machine describes the same print, not the same shelf of filament.
 13	//
 14	// GUI-free and Orca-free: the store holds preset *names* and hex strings, so
 15	// it can be tested without wx, a PresetBundle, or a data directory. Selecting
 16	// a spool -- which does touch Orca -- belongs to Shell/SetupCommands.
 17	
 18	#include <cstdint>
 19	#include <functional>
 20	#include <optional>
 21	#include <string>
 22	#include <vector>
 23	
 24	namespace Slic3r::GUI::JusPrin::Workspace {
 25	
 26	struct Spool
 27	{
 28	    std::string id;              // opaque, unique within the store
 29	    std::string printer_preset;  // Orca printer preset this spool belongs to
 30	    std::string filament_preset; // Orca filament preset name
 31	    std::string colour;          // "#RRGGBB"
 32	    std::string name;            // user-visible and editable
 33	    std::string brand;           // vendor cached from the preset at creation
 34	    std::string last_used;       // ISO-8601 UTC
 35	
 36	    bool operator==(const Spool& rhs) const
 37	    {
 38	        return id == rhs.id && printer_preset == rhs.printer_preset && filament_preset == rhs.filament_preset &&
 39	               colour == rhs.colour && name == rhs.name && brand == rhs.brand && last_used == rhs.last_used;
 40	    }
 41	};
 42	
 43	// A JSON file of spools, loaded once at construction and written through on
 44	// every mutation. Small by design: a person keeps three to fifteen spools, so
 45	// there is no index, no cache, and no partial write.
 46	class SpoolStore
 47	{
 48	public:
 49	    struct Config
 50	    {
 51	        // Absolute path of the JSON file. Required.
 52	        std::string file_path;
 53	        // Injectable for deterministic tests.
 54	        std::function<std::string()> clock; // ISO-8601 UTC timestamp
 55	        std::function<std::string()> uuid;  // opaque unique identifier
 56	    };
 57	
 58	    // Reads the file. A missing file is an empty store, which is the ordinary
 59	    // first-run state.
 60	    //
 61	    // A file that exists but does not parse is moved aside to
 62	    // "<file_path>.corrupt" and the store starts empty. Overwriting it would
 63	    // destroy spools the person named by hand, and refusing to start would
 64	    // take the chip down over a file the product can rebuild by seeding. The
 65	    // move is reported through corrupt(), so the state stays visible rather
 66	    // than being logged and forgotten.
 67	    explicit SpoolStore(Config config);
 68	
 69	    SpoolStore(const SpoolStore&) = delete;
 70	    SpoolStore& operator=(const SpoolStore&) = delete;
 71	
 72	    // True when the backing file existed, could not be parsed, and was moved
 73	    // aside by this constructor.
 74	    bool               corrupt() const { return m_corrupt; }
 75	    const std::string& corrupt_reason() const { return m_corrupt_reason; }
 76	
 77	    // Every spool for this printer, most recently used first. Ties break on
 78	    // id so the order is stable across runs.
 79	    std::vector<Spool> spools_for(const std::string& printer_preset) const;
 80	
 81	    // The spool whose filament preset and colour both match what the project
 82	    // currently has loaded, or nothing when the project does not correspond to
 83	    // a remembered spool.
 84	    std::optional<Spool> current(const std::string& printer_preset,
 85	                                 const std::string& filament_preset,
 86	                                 const std::string& colour) const;
 87	
 88	    std::optional<Spool> find(const std::string& id) const;
 89	
 90	    // Assigns id and last_used, stores, and returns the stored record.
 91	    Spool add(Spool spool);
 92	
 93	    // Each returns false when the id is unknown; the caller owns the decision
 94	    // about a stale menu, so an unknown id is a normal answer here rather than
 95	    // an error.
 96	    bool rename(const std::string& id, const std::string& name);
 97	    bool recolour(const std::string& id, const std::string& colour);
 98	    bool remove(const std::string& id);
 99	    bool touch(const std::string& id);
100	
101	    // A printer is its Orca printer preset, so renaming the preset moves its
102	    // spools and removing it takes them along. Each returns how many spools
103	    // changed; a printer with none is a normal answer.
104	    std::size_t move_printer(const std::string& from, const std::string& to);
105	    std::size_t remove_printer(const std::string& printer_preset);
106	
107	    std::size_t size() const { return m_spools.size(); }
108	
109	private:
110	    // Write temp, rename over. Throws when the write fails: a spool the person
111	    // just named must not silently fail to persist.
112	    void write();
113	
114	    Config             m_config;
115	    std::vector<Spool> m_spools;
116	    bool               m_corrupt{false};
117	    std::string        m_corrupt_reason;
118	};
119	
120	} // namespace Slic3r::GUI::JusPrin::Workspace
  1	#include "SpoolStore.hpp"
  2	#include "UtcTime.hpp"
  3	
  4	#include <nlohmann/json.hpp>
  5	
  6	#include <algorithm>
  7	#include <chrono>
  8	#include <ctime>
  9	#include <filesystem>
 10	#include <fstream>
 11	#include <random>
 12	#include <sstream>
 13	#include <stdexcept>
 14	
 15	namespace Slic3r::GUI::JusPrin::Workspace {
 16	
 17	namespace {
 18	
 19	namespace fs = std::filesystem;
 20	using nlohmann::json;
 21	
 22	constexpr int kSchemaVersion = 1;
 23	
 24	std::string default_clock() { return Workspace::utc_now(); }
 25	
 26	std::string default_uuid()
 27	{
 28	    static std::mt19937_64 engine(std::random_device{}());
 29	    std::uniform_int_distribution<std::uint64_t> distribution;
 30	    std::ostringstream out;
 31	    out << std::hex << distribution(engine) << '-' << distribution(engine);
 32	    return out.str();
 33	}
 34	
 35	Spool spool_from(const json& entry)
 36	{
 37	    Spool spool;
 38	    spool.id              = entry.at("id").get<std::string>();
 39	    spool.printer_preset  = entry.at("printer_preset").get<std::string>();
 40	    spool.filament_preset = entry.at("filament_preset").get<std::string>();
 41	    spool.colour          = entry.at("colour").get<std::string>();
 42	    spool.name            = entry.at("name").get<std::string>();
 43	    spool.brand           = entry.value("brand", std::string{});
 44	    spool.last_used       = entry.value("last_used", std::string{});
 45	    return spool;
 46	}
 47	
 48	json json_from(const Spool& spool)
 49	{
 50	    return json{{"id", spool.id},
 51	                {"printer_preset", spool.printer_preset},
 52	                {"filament_preset", spool.filament_preset},
 53	                {"colour", spool.colour},
 54	                {"name", spool.name},
 55	                {"brand", spool.brand},
 56	                {"last_used", spool.last_used}};
 57	}
 58	
 59	} // namespace
 60	
 61	SpoolStore::SpoolStore(Config config) : m_config(std::move(config))
 62	{
 63	    if (m_config.file_path.empty())
 64	        throw std::invalid_argument("SpoolStore requires a file path");
 65	    if (!m_config.clock)
 66	        m_config.clock = default_clock;
 67	    if (!m_config.uuid)
 68	        m_config.uuid = default_uuid;
 69	
 70	    const fs::path path(m_config.file_path);
 71	    std::error_code ec;
 72	    if (!fs::exists(path, ec))
 73	        return;
 74	
 75	    std::string text;
 76	    {
 77	        std::ifstream in(path, std::ios::binary);
 78	        if (!in.is_open()) {
 79	            m_corrupt        = true;
 80	            m_corrupt_reason = "spools file could not be opened";
 81	            return;
 82	        }
 83	        std::stringstream buffer;
 84	        buffer << in.rdbuf();
 85	        text = buffer.str();
 86	    }
 87	
 88	    // A damaged file is data the person cannot get back. Parse defensively
 89	    // here -- and only here -- then move the file aside so the next write
 90	    // cannot overwrite it. Everything past this point treats the in-memory
 91	    // vector as authoritative.
 92	    try {
 93	        const json document = json::parse(text);
 94	        for (const auto& entry : document.at("spools"))
 95	            m_spools.push_back(spool_from(entry));
 96	    } catch (const json::exception& error) {
 97	        m_spools.clear();
 98	        m_corrupt        = true;
 99	        m_corrupt_reason = error.what();
100	    }
101	
102	    if (m_corrupt) {
103	        fs::rename(path, path.string() + ".corrupt", ec);
104	        if (ec)
105	            m_corrupt_reason += "; the damaged file could not be moved aside: " + ec.message();
106	    }
107	}
108	
109	std::vector<Spool> SpoolStore::spools_for(const std::string& printer_preset) const
110	{
111	    std::vector<Spool> matches;
112	    for (const Spool& spool : m_spools)
113	        if (spool.printer_preset == printer_preset)
114	            matches.push_back(spool);
115	    std::sort(matches.begin(), matches.end(), [](const Spool& a, const Spool& b) {
116	        if (a.last_used != b.last_used)
117	            return a.last_used > b.last_used;
118	        return a.id < b.id;
119	    });
120	    return matches;
121	}
122	
123	std::optional<Spool> SpoolStore::current(const std::string& printer_preset,
124	                                         const std::string& filament_preset,
125	                                         const std::string& colour) const
126	{
127	    // Most recently used wins when two spools of the same preset share a
128	    // colour, which is the same order the menu shows.
129	    for (const Spool& spool : spools_for(printer_preset))
130	        if (spool.filament_preset == filament_preset && spool.colour == colour)
131	            return spool;
132	    return std::nullopt;
133	}
134	
135	std::optional<Spool> SpoolStore::find(const std::string& id) const
136	{
137	    const auto found = std::find_if(m_spools.begin(), m_spools.end(), [&](const Spool& s) { return s.id == id; });
138	    return found == m_spools.end() ? std::nullopt : std::optional<Spool>(*found);
139	}
140	
141	Spool SpoolStore::add(Spool spool)
142	{
143	    spool.id        = m_config.uuid();
144	    spool.last_used = m_config.clock();
145	    m_spools.push_back(spool);
146	    write();
147	    return spool;
148	}
149	
150	bool SpoolStore::rename(const std::string& id, const std::string& name)
151	{
152	    auto found = std::find_if(m_spools.begin(), m_spools.end(), [&](const Spool& s) { return s.id == id; });
153	    if (found == m_spools.end())
154	        return false;
155	    found->name = name;
156	    write();
157	    return true;
158	}
159	
160	bool SpoolStore::recolour(const std::string& id, const std::string& colour)
161	{
162	    auto found = std::find_if(m_spools.begin(), m_spools.end(), [&](const Spool& s) { return s.id == id; });
163	    if (found == m_spools.end())
164	        return false;
165	    found->colour = colour;
166	    write();
167	    return true;
168	}
169	
170	bool SpoolStore::remove(const std::string& id)
171	{
172	    auto found = std::find_if(m_spools.begin(), m_spools.end(), [&](const Spool& s) { return s.id == id; });
173	    if (found == m_spools.end())
174	        return false;
175	    m_spools.erase(found);
176	    write();
177	    return true;
178	}
179	
180	std::size_t SpoolStore::move_printer(const std::string& from, const std::string& to)
181	{
182	    std::size_t moved = 0;
183	    for (Spool& spool : m_spools)
184	        if (spool.printer_preset == from) {
185	            spool.printer_preset = to;
186	            ++moved;
187	        }
188	    if (moved > 0)
189	        write();
190	    return moved;
191	}
192	
193	std::size_t SpoolStore::remove_printer(const std::string& printer_preset)
194	{
195	    const auto before = m_spools.size();
196	    m_spools.erase(std::remove_if(m_spools.begin(), m_spools.end(),
197	                                  [&](const Spool& s) { return s.printer_preset == printer_preset; }),
198	                   m_spools.end());
199	    const std::size_t removed = before - m_spools.size();
200	    if (removed > 0)
201	        write();
202	    return removed;
203	}
204	
205	bool SpoolStore::touch(const std::string& id)
206	{
207	    auto found = std::find_if(m_spools.begin(), m_spools.end(), [&](const Spool& s) { return s.id == id; });
208	    if (found == m_spools.end())
209	        return false;
210	    found->last_used = m_config.clock();
211	    write();
212	    return true;
213	}
214	
215	void SpoolStore::write()
216	{
217	    json document;
218	    document["version"] = kSchemaVersion;
219	    document["spools"]  = json::array();
220	    for (const Spool& spool : m_spools)
221	        document["spools"].push_back(json_from(spool));
222	
223	    const fs::path path(m_config.file_path);
224	    std::error_code ec;
225	    fs::create_directories(path.parent_path(), ec);
226	
227	    const fs::path temp = path.string() + ".tmp";
228	    {
229	        std::ofstream out(temp, std::ios::binary | std::ios::trunc);
230	        if (!out.is_open())
231	            throw std::runtime_error("could not open " + temp.string() + " to save spools");
232	        out << document.dump(2);
233	        if (!out.good())
234	            throw std::runtime_error("could not write " + temp.string());
235	    }
236	    fs::rename(temp, path, ec);
237	    if (ec)
238	        throw std::runtime_error("could not save spools to " + path.string() + ": " + ec.message());
239	}
240	
241	} // namespace Slic3r::GUI::JusPrin::Workspace

