 48	json json_from(const Spool& spool)
 49	{
 50	    return json{{"id", spool.id},
 51	                {"printer_preset", spool.printer_preset},
 52	                {"filament_preset", spool.filament_preset},
 53	                {"colour", spool.colour},
 54	                {"name", spool.name},
 55	                {"brand", spool.brand},
 56	                {"last_used", spool.last_used}};
 57	}
 58	
 59	} // namespace
 60	
 61	SpoolStore::SpoolStore(Config config) : m_config(std::move(config))
 62	{
 63	    if (m_config.file_path.empty())
 64	        throw std::invalid_argument("SpoolStore requires a file path");
 65	    if (!m_config.clock)
 66	        m_config.clock = default_clock;
 67	    if (!m_config.uuid)
 68	        m_config.uuid = default_uuid;
 69	
 70	    const fs::path path(m_config.file_path);
 71	    std::error_code ec;
 72	    if (!fs::exists(path, ec))
 73	        return;
 74	
 75	    std::string text;
 76	    {
 77	        std::ifstream in(path, std::ios::binary);
 78	        if (!in.is_open()) {
 79	            m_corrupt        = true;
 80	            m_corrupt_reason = "spools file could not be opened";
 81	            return;
 82	        }
 83	        std::stringstream buffer;
 84	        buffer << in.rdbuf();
 85	        text = buffer.str();
 86	    }
 87	
 88	    // A damaged file is data the person cannot get back. Parse defensively
 89	    // here -- and only here -- then move the file aside so the next write
 90	    // cannot overwrite it. Everything past this point treats the in-memory
 91	    // vector as authoritative.
 92	    try {
 93	        const json document = json::parse(text);
 94	        for (const auto& entry : document.at("spools"))
 95	            m_spools.push_back(spool_from(entry));
 96	    } catch (const json::exception& error) {
 97	        m_spools.clear();
 98	        m_corrupt        = true;
 99	        m_corrupt_reason = error.what();
100	    }
101	
102	    if (m_corrupt) {
103	        fs::rename(path, path.string() + ".corrupt", ec);
104	        if (ec)
105	            m_corrupt_reason += "; the damaged file could not be moved aside: " + ec.message();
106	    }
107	}
108	
109	std::vector<Spool> SpoolStore::spools_for(const std::string& printer_preset) const
110	{
111	    std::vector<Spool> matches;
112	    for (const Spool& spool : m_spools)
113	        if (spool.printer_preset == printer_preset)
114	            matches.push_back(spool);
115	    std::sort(matches.begin(), matches.end(), [](const Spool& a, const Spool& b) {
116	        if (a.last_used != b.last_used)
117	            return a.last_used > b.last_used;
118	        return a.id < b.id;
119	    });
120	    return matches;
121	}
122	
123	std::optional<Spool> SpoolStore::current(const std::string& printer_preset,
124	                                         const std::string& filament_preset,
125	                                         const std::string& colour) const
126	{
127	    // Most recently used wins when two spools of the same preset share a
128	    // colour, which is the same order the menu shows.
129	    for (const Spool& spool : spools_for(printer_preset))
130	        if (spool.filament_preset == filament_preset && spool.colour == colour)
131	            return spool;
132	    return std::nullopt;
133	}
134	
135	std::optional<Spool> SpoolStore::find(const std::string& id) const
136	{
137	    const auto found = std::find_if(m_spools.begin(), m_spools.end(), [&](const Spool& s) { return s.id == id; });
138	    return found == m_spools.end() ? std::nullopt : std::optional<Spool>(*found);
139	}
140	
141	Spool SpoolStore::add(Spool spool)
142	{
143	    spool.id        = m_config.uuid();
144	    spool.last_used = m_config.clock();
145	    m_spools.push_back(spool);
146	    write();
147	    return spool;
148	}
149	
150	bool SpoolStore::rename(const std::string& id, const std::string& name)
151	{
152	    auto found = std::find_if(m_spools.begin(), m_spools.end(), [&](const Spool& s) { return s.id == id; });
153	    if (found == m_spools.end())
154	        return false;
155	    found->name = name;
156	    write();
157	    return true;
158	}
159	
160	bool SpoolStore::recolour(const std::string& id, const std::string& colour)
161	{
162	    auto found = std::find_if(m_spools.begin(), m_spools.end(), [&](const Spool& s) { return s.id == id; });
163	    if (found == m_spools.end())
164	        return false;
165	    found->colour = colour;
166	    write();
167	    return true;
168	}
169	
170	bool SpoolStore::remove(const std::string& id)
171	{
172	    auto found = std::find_if(m_spools.begin(), m_spools.end(), [&](const Spool& s) { return s.id == id; });
173	    if (found == m_spools.end())
174	        return false;
175	    m_spools.erase(found);
176	    write();
177	    return true;
178	}
179	
180	std::size_t SpoolStore::move_printer(const std::string& from, const std::string& to)
181	{
182	    std::size_t moved = 0;
183	    for (Spool& spool : m_spools)
184	        if (spool.printer_preset == from) {
185	            spool.printer_preset = to;
186	            ++moved;
187	        }
188	    if (moved > 0)
189	        write();
190	    return moved;
191	}
192	
193	std::size_t SpoolStore::remove_printer(const std::string& printer_preset)
194	{
195	    const auto before = m_spools.size();
196	    m_spools.erase(std::remove_if(m_spools.begin(), m_spools.end(),
197	                                  [&](const Spool& s) { return s.printer_preset == printer_preset; }),
198	                   m_spools.end());
199	    const std::size_t removed = before - m_spools.size();
200	    if (removed > 0)
201	        write();
202	    return removed;
203	}
204	
205	bool SpoolStore::touch(const std::string& id)
206	{
207	    auto found = std::find_if(m_spools.begin(), m_spools.end(), [&](const Spool& s) { return s.id == id; });
208	    if (found == m_spools.end())
209	        return false;
210	    found->last_used = m_config.clock();
211	    write();
212	    return true;
213	}
214	
215	void SpoolStore::write()
216	{
217	    json document;
218	    document["version"] = kSchemaVersion;
219	    document["spools"]  = json::array();
220	    for (const Spool& spool : m_spools)
221	        document["spools"].push_back(json_from(spool));
222	
223	    const fs::path path(m_config.file_path);
224	    std::error_code ec;
225	    fs::create_directories(path.parent_path(), ec);
226	
227	    const fs::path temp = path.string() + ".tmp";
228	    {
229	        std::ofstream out(temp, std::ios::binary | std::ios::trunc);
230	        if (!out.is_open())
231	            throw std::runtime_error("could not open " + temp.string() + " to save spools");
232	        out << document.dump(2);
233	        if (!out.good())
234	            throw std::runtime_error("could not write " + temp.string());
235	    }
236	    fs::rename(temp, path, ec);
237	    if (ec)
238	        throw std::runtime_error("could not save spools to " + path.string() + ": " + ec.message());
239	}
240	
241	} // namespace Slic3r::GUI::JusPrin::Workspace

