31	namespace {
32	
33	// Joining a wxString to a narrow literal decodes that literal through the
34	// locale's encoding -- UTF-8 on macOS, the ANSI code page on Windows, where
35	// these separators come out as the two or three characters their UTF-8 bytes
36	// happen to spell. Naming them once, decoded explicitly, keeps a separator
37	// from being written the unsafe way again.
38	const wxString& middle_dot() { static const wxString s = wxString::FromUTF8(" \xC2\xB7 "); return s; }
39	const wxString& em_dash()    { static const wxString s = wxString::FromUTF8(" \xE2\x80\x94 "); return s; }
40	
41	// The header row is taller than any component recipe; no token names it. It
42	// is not a spacing step either, so it is written once here.
43	constexpr int kHeaderHeightDip = 56;
44	
45	} // namespace
46	
47	StatusRow::StatusRow(wxWindow*                  parent,
48	                     const ShellTheme&          theme,
49	                     Plater&                    plater,
50	                     Notebook&                  tabpanel,
51	                     Agent::ProjectPersistence& persistence)
52	    : wxPanel(parent, wxID_ANY)
53	    , m_theme(theme)
54	    , m_plater(plater)
55	    , m_tabpanel(tabpanel)
56	    , m_persistence(persistence)
57	{
58	    SetName("Project header");
59	    Workspace::SpoolStore::Config spool_config;
60	    spool_config.file_path = (boost::filesystem::path(data_dir()) / "jusprin" / "spools.json").string();
61	    m_spools = std::make_unique<Workspace::SpoolStore>(std::move(spool_config));
62	    if (m_spools->corrupt()) {
63	        // Visible, and the person's own file is preserved next to it. The chip
64	        // still works: it reseeds from whatever the project has loaded.
65	        BOOST_LOG_TRIVIAL(error) << "JusPrin: spools.json was damaged and has been moved aside: "
66	                                 << m_spools->corrupt_reason();
67	    }
68	    SetBackgroundStyle(wxBG_STYLE_PAINT);
69	    SetMinSize(wxSize(-1, FromDIP(kHeaderHeightDip)));
70	    m_home_button = new HeaderButton(this, theme, HeaderStyle::Quiet, _L("Home"), HeaderIcon::Back);
71	    m_home_button->SetName("Home navigation");
72	    m_chip = new PrinterSpoolChip(this, theme);
73	    m_slice_button = new HeaderButton(this, theme, HeaderStyle::PrimaryLeft, _L("Slice"), HeaderIcon::Slice);
74	    m_slice_button->SetName("Next print action");
75	    m_menu_button = new HeaderButton(this, theme, HeaderStyle::PrimaryRight, wxEmptyString, HeaderIcon::Down);
76	    m_menu_button->SetName(_L("Print actions"));
77	    m_overflow_button = new HeaderButton(this, theme, HeaderStyle::Outline, wxEmptyString, HeaderIcon::More);
78	    m_overflow_button->SetName("Project actions");
79	    m_overflow_button->SetToolTip(_L("Project details and preferences"));
80	    m_agent_toggle = new HeaderButton(this, theme, HeaderStyle::Outline, wxEmptyString, HeaderIcon::PanelOpen);
81	    m_agent_toggle->SetName("Agent panel");
82	    m_agent_toggle->SetToolTip(_L("Hide the Agent panel"));
83	    m_agent_toggle->Hide();
84	    m_agent_toggle->Bind(wxEVT_BUTTON, [this](wxCommandEvent&) { toggle_agent_pane(); });
85	    m_home_button->Bind(wxEVT_BUTTON, [this](wxCommandEvent&) { request_home(); });
86	    m_chip->on_printer_activated([this] { open_printer_menu(); });
87	    m_chip->on_spool_activated([this] { open_spool_menu(); });
88	    m_overflow_button->Bind(wxEVT_BUTTON, [this](wxCommandEvent&) { show_overflow_menu(); });
89	    Bind(wxEVT_SIZE, [this](wxSizeEvent& e) { layout_header(); e.Skip(); });
90	    Bind(wxEVT_PAINT, [this](wxPaintEvent&) {
91	        wxAutoBufferedPaintDC dc(this);
92	        const auto& p = m_theme.palette(m_dark);
93	        dc.SetBackground(wxBrush(p.surface_canvas)); dc.Clear();
94	        dc.SetPen(wxPen(p.border_subtle));
95	        dc.DrawLine(0, GetClientSize().y-1, GetClientSize().x, GetClientSize().y-1);
96	    });
97	
98	    m_slice_button->Bind(wxEVT_BUTTON, [this](wxCommandEvent&) {
99	        request_action(primary_print_action(action_state()).primary.action);
100	    });
101	    m_menu_button->Bind(wxEVT_BUTTON, [this](wxCommandEvent&) {
102	        if (action_state().slicing) request_action(PrintAction::Cancel);
103	        else show_action_menu();
104	    });
105	
106	    Bind(wxEVT_SYS_COLOUR_CHANGED, [this](wxSysColourChangedEvent& event) {
107	        apply_appearance(GUI_App::dark_mode());
108	        event.Skip();
109	    });
110	
111	    m_project_state_subscription = m_plater.subscribe_project_state(
112	        [this](const ProjectStateChanged&) { refresh(); });
113	    // A recorded print and a replaced document both change the print count
114	    // without publishing a project-state change, so the ledger is observed
115	    // separately. Persistence outlives this row in both teardown orders, and
116	    // the destructor clears the slot.
117	    m_persistence.set_ledger_listener([this]() { refresh(); });
118	    m_plater.Bind(EVT_SLICE_STATUS_CHANGED, &StatusRow::on_slice_status_changed, this);
119	    // The tab panel and this row are siblings, so wx may destroy either one
120	    // first at shutdown; only unbind while the tab panel still exists.
121	    m_tabpanel.Bind(wxEVT_DESTROY, &StatusRow::on_tabpanel_destroyed, this);
122	}
