276	void StatusRow::layout_header()
277	{
278	    const int margin = FromDIP(16), gap = FromDIP(8), height = GetClientSize().y;
279	    auto place = [height](HeaderButton* button, int x, int width = -1) {
280	        wxSize size = button->GetBestSize();
281	        if (width >= 0) size.x = width;
282	        button->SetSize(x,(height-size.y)/2,size.x,size.y);
283	    };
284	    int right = GetClientSize().x-margin-m_overflow_button->GetBestSize().x;
285	    place(m_overflow_button,right);
286	    right -= gap;
287	    if (m_agent_toggle->IsShown()) {
288	        right -= m_agent_toggle->GetBestSize().x;
289	        place(m_agent_toggle,right);
290	        right -= gap;
291	    }
292	    if (m_menu_button->IsShown()) {
293	        right -= m_menu_button->GetBestSize().x;
294	        place(m_menu_button,right);
295	    }
296	    right -= m_slice_button->GetBestSize().x;
297	    place(m_slice_button,right);
298	    place(m_home_button,margin);
299	    const int left = margin+m_home_button->GetBestSize().x+gap;
300	    const int available = std::max(0,right-gap-left);
301	    const int width = std::min(m_chip->GetBestSize().x,available);
302	    const wxSize chip = m_chip->GetBestSize();
303	    m_chip->SetSize(left+(available-width)/2,(height-chip.y)/2,width,chip.y);
304	}
