320	std::optional<Workspace::Spool> StatusRow::current_spool()
321	{
322	    const auto printer  = SetupCommands::current_printer();
323	    const auto filament = SetupCommands::current_filament();
324	    if (!printer.valid || !filament.valid)
325	        return std::nullopt;
326	    const std::string colour = SetupCommands::current_colour().ToStdString();
327	
328	    if (auto matched = m_spools->current(printer.preset_name, filament.preset_name, colour))
329	        return matched;
330	    // A printer with no remembered spools gets its first one from whatever the
331	    // project already has loaded, so the chip's right half is never empty and
332	    // the person starts with a list of one rather than a list of none. A
333	    // printer that already has spools and is on some other preset simply has
334	    // no current spool; guessing a new one on every project would fill the
335	    // list with entries nobody chose.
336	    if (!m_spools->spools_for(printer.preset_name).empty())
337	        return std::nullopt;
338	
339	    Workspace::Spool seed;
340	    seed.printer_preset  = printer.preset_name;
341	    seed.filament_preset = filament.preset_name;
342	    seed.colour          = colour;
343	    seed.brand           = filament.vendor.ToStdString();
344	    const wxString word  = SetupCommands::colour_word(wxColour(SetupCommands::current_colour()));
345	    const wxString label = word.empty() ? filament.alias : word + " " + filament.material;
346	    seed.name            = (label.empty() ? filament.alias : label).ToStdString();
347	    return m_spools->add(std::move(seed));
348	}
