374	void StatusRow::open_spool_menu()
375	{
376	    SpoolMenu::Host host;
377	    host.store  = m_spools.get();
378	    host.plater = &m_plater;
379	    host.selected = [self = wxWeakRef<StatusRow>(this)](const Workspace::Spool& spool) {
380	        if (self) self->on_spool_selected(spool);
381	    };
382	    host.store_changed = [self = wxWeakRef<StatusRow>(this)] { if (self) self->refresh(); };
383	    SpoolMenu::open(this, m_theme, m_dark, std::move(host), m_chip->spool_half());
384	}
385	
386	// A swap changes three things and nothing else: the chip's right half and the
387	// pinned card both follow Orca's own settings-changed notification, and one
388	// grey line lands at the end of the thread. The line reports; it never offers
389	// to undo, because the selection belongs to the chip.
390	void StatusRow::on_spool_selected(const Workspace::Spool& spool)
391	{
392	    refresh();
393	    if (!m_note_sink) return;
394	    wxString note = wxString::Format(_L("Spool is now %s"), wxString::FromUTF8(spool.name));
395	    if (!spool.brand.empty()) note += wxString::Format(" (%s)", wxString::FromUTF8(spool.brand));
396	    note += ".";
397	    const auto filament = SetupCommands::current_filament();
398	    if (!filament.material.empty())
399	        note += " " + wxString::Format(_L("Heat and cooling follow %s; walls and infill unchanged."), filament.material);
400	    note += " " + _L("Slice again when ready.");
401	    m_note_sink(note);
402	}
