404	bool StatusRow::select_spool(const std::string& spool_id)
405	{
406	    const auto printer = SetupCommands::current_printer();
407	    const auto spool   = m_spools->find(spool_id);
408	    // A spool belonging to another printer is not a stale menu row, it is a
409	    // wrong instruction; refusing it keeps the mistake visible to the caller.
410	    if (!spool || spool->printer_preset != printer.preset_name)
411	        return false;
412	    if (!SetupCommands::select_filament_preset(m_plater, spool->filament_preset))
413	        return false;
414	    if (const wxColour colour(wxString::FromUTF8(spool->colour)); colour.IsOk())
415	        SetupCommands::set_filament_colour(m_plater, colour);
416	    m_spools->touch(spool->id);
417	    on_spool_selected(*spool);
418	    return true;
419	}
