35	// Thumbnails travel as base64 data: URLs, so the whole gallery's images sit in
36	// one envelope. The cap bounds that payload; projects past it keep their card
37	// and its frame, without an image.
38	constexpr int kThumbnailCap = 30;
39	
40	std::string utf8(const std::wstring& text) { return std::string(wxString(text).ToUTF8()); }
41	
42	// "C:/models/garage bracket.3mf" -> "garage bracket", the form a print job on
43	// a device carries, and the form a card is titled by.
44	std::string file_stem(const std::wstring& path)
45	{
46	    const std::wstring name = path.substr(path.find_last_of(L"/\\") + 1);
47	    const size_t       dot  = name.find_last_of(L'.');
48	    return utf8(dot == std::wstring::npos ? name : name.substr(0, dot));
49	}
50	
51	// Upstream's own predicate, not a copy of it. The first version of this listed
52	// RUNNING, PAUSE and SLICING and left out PREPARE, so a printer that was
53	// preparing a job showed on Home as idle. One implementation cannot drift from
54	// itself.
55	bool machine_is_printing(const MachineObject& machine)
56	{
57	    return MachineObject::is_in_printing_status(machine.print_status);
58	}
59	
60	// The separator the design uses inside a status line, as the shell's status
61	// row does. Kept local for the same reason it is local there: it is a
62	// punctuation constant, not an interface.
63	const wxString& middle_dot()
64	{
65	    static const wxString s = wxString::FromUTF8(" \xC2\xB7 ");
66	    return s;
67	}
68	
69	// "2h 14m left", "14m left", or empty when the device has not estimated yet.
70	// The card omits the clause rather than showing a zero.
71	wxString remaining_text(int seconds)
72	{
73	    if (seconds <= 0)
74	        return wxEmptyString;
75	    const int minutes = seconds / 60;
76	    if (minutes >= 60)
77	        return wxString::Format(_L("%dh %dm left"), minutes / 60, minutes % 60);
78	    return wxString::Format(_L("%dm left"), std::max(minutes, 1));
79	}
80	
81	// A card id says what the card stands for, so an action never has to guess
82	// whether a name is a printer or a device serial.
83	const std::string kNamedPrefix  = "named:";
84	const std::string kDevicePrefix = "device:";
85	
86	// The rest of `id` after `prefix`, or nothing when it has another prefix.
87	std::optional<std::string> strip(const std::string& id, const std::string& prefix)
88	{
89	    if (id.compare(0, prefix.size(), prefix) != 0)
90	        return std::nullopt;
91	    return id.substr(prefix.size());
92	}
93	
94	std::string utf8(const wxString& text) { return std::string(text.ToUTF8()); }
95	
96	// "X1 Carbon" for the model a profile or a device names: the profile's
97	// "Bambu Lab X1 Carbon", or a device's own id, "BL-P001". The loaded vendor
98	// profiles answer, as the catalogue would without reading its files again.
99	// The brand stays when the rest is only a number: "2.4 350" names no printer,
100	// "Voron 2.4 350" does. A profile model no vendor lists keeps its own name; a
101	// device id, nothing.
102	std::string model_name(const std::string& printer_model, const std::string& device_model_id = {})
103	{
104	    for (const auto& [id, vendor] : wxGetApp().preset_bundle->vendors)
105	        for (const VendorProfile::PrinterModel& model : vendor.models)
106	            if (printer_model.empty() ? !device_model_id.empty() && model.model_id == device_model_id
107	                                      : model.id == printer_model) {
108	                const std::string rest = PrinterSetup::split_brand(vendor.name, model.id).second;
109	                return !rest.empty() && std::isdigit(static_cast<unsigned char>(rest.front())) ? model.id : rest;
110	            }
111	    return printer_model;
112	}
113	
114	// "X1 Carbon · 0.4 mm", or whichever half is known.
115	std::string model_text(const std::string& model, double nozzle)
116	{
117	    wxString text = wxString::FromUTF8(model);
118	    if (nozzle > 0.)
119	        text += (text.empty() ? wxString() : middle_dot()) + wxString::Format("%g mm", nozzle);
120	    return utf8(text);
121	}
122	
123	// "192.168.1.42:7125" for "http://192.168.1.42:7125/": the host and port as
124	// saved, without the scheme, a path, or any credentials written into it.
125	std::string host_address(const std::string& print_host)
126	{
127	    std::string address = print_host;
128	    if (const size_t scheme = address.find("://"); scheme != std::string::npos)
129	        address = address.substr(scheme + 3);
130	    address = address.substr(0, address.find('/'));
131	    if (const size_t at = address.rfind('@'); at != std::string::npos)
132	        address = address.substr(at + 1);
133	    return address.empty() ? print_host : address;
134	}
135	
136	double reported_nozzle(MachineObject& machine)
137	{
138	    const DevExtderSystem* extruders = machine.GetExtderSystem();
139	    return extruders != nullptr ? extruders->GetNozzleDiameter(0) : 0.;
140	}
141	
142	// What the device reports about itself and its job. The connection line is
143	// the device's only when it has something verified to say; otherwise the
144	// card keeps what it had.
145	void describe_device(MachineObject& machine, PrinterEntry& printer)
146	{
147	    const bool printing        = machine_is_printing(machine);
148	    const bool connected       = PrinterSetup::has_recent_printer_data(machine);
149	    printer.state              = !connected ? PrinterState::Offline
150	                                 : printing ? PrinterState::Printing
151	                                            : PrinterState::Idle;
152	    printer.can_launch_monitor = connected;
153	    if (printing) {
154	        printer.progress_percent = machine.mc_print_percent;
155	        wxString status          = _L("Printing") + middle_dot() + wxString::Format("%d%%", machine.mc_print_percent);
156	        const wxString remaining = remaining_text(machine.mc_left_time);
157	        if (!remaining.empty())
158	            status += middle_dot() + remaining;
159	        printer.status_text = std::string(status.ToUTF8());
160	    }
161	    const std::string kind = machine.connection_type();
162	    if (connected) {
163	        printer.connection_state  = ConnectionState::Online;
164	        printer.connection_kind   = kind;
165	        printer.connection_text   = utf8(_L("Online") + middle_dot() + (kind == "lan" ? _L("LAN") : _L("Cloud")));
166	        printer.connection_action = "";
167	    } else if (PrinterSetup::has_verified_printer_connection(machine.get_dev_id())) {
168	        printer.connection_state  = ConnectionState::Offline;
169	        printer.connection_kind   = kind;
170	        printer.connection_text   = utf8(_L("Offline"));
171	        printer.connection_action = "reconnect";
172	    }
173	}
174	
175	MachineObject* my_machine(const std::string& device_id)
176	{
177	    DeviceManager* devices = wxGetApp().getDeviceManager();
178	    return devices != nullptr ? devices->get_my_machine(device_id) : nullptr;
179	}
180	
181	// The filament type a spool's preset names ("PLA"), or empty.
182	std::string filament_type(const std::string& filament_preset)
183	{
184	    const Preset* preset = wxGetApp().preset_bundle->filaments.find_preset(filament_preset, false, true);
185	    if (preset == nullptr)
186	        return {};
187	    const auto* type = preset->config.option<ConfigOptionStrings>("filament_type");
188	    return type != nullptr && !type->values.empty() ? type->values.front() : std::string();
189	}
