199	bool OrcaHomeBackend::dark() const { return wxGetApp().dark_mode(); }
200	
201	std::vector<ProjectEntry> OrcaHomeBackend::recent_projects() const
202	{
203	    // Which project each printing machine is running, so a card can say so.
204	    // This is the only per-project status the codebase can answer today; the
205	    // rest is the file's own modified time until a project-state store exists.
206	    std::map<std::string, std::string> printing_by_stem;
207	    if (DeviceManager* devices = wxGetApp().getDeviceManager()) {
208	        for (const auto& entry : devices->get_my_machine_list()) {
209	            MachineObject* machine = entry.second;
210	            if (machine == nullptr)
211	                continue;
212	            if (machine_is_printing(*machine) && !machine->subtask_name.empty())
213	                printing_by_stem.emplace(machine->subtask_name, machine->get_dev_name());
214	        }
215	    }
216	
217	    std::vector<ProjectEntry>    projects;
218	    boost::property_tree::wptree recent;
219	    m_frame.get_recent_projects(recent, kThumbnailCap);
220	    size_t index = 0;
221	    for (const auto& node : recent) {
222	        const auto&  item = node.second;
223	        ProjectEntry project;
224	        project.id              = std::to_string(index++);
225	        const std::wstring path = item.get<std::wstring>(L"path", L"");
226	        project.name            = file_stem(path);
227	        project.path            = utf8(path);
228	        project.thumbnail_url   = utf8(item.get<std::wstring>(L"image", L""));
229	
230	        const auto printing = printing_by_stem.find(file_stem(path));
231	        if (printing != printing_by_stem.end()) {
232	            project.status_kind = ProjectStatusKind::Printing;
233	            project.status_text = std::string(
234	                wxString::Format(_L("Printing on %s"), wxString::FromUTF8(printing->second)).ToUTF8());
235	        } else {
236	            // Honest about what is known: nothing records whether this project
237	            // is sliced, so the card shows when it was last written, and says
238	            // which fact it is showing rather than dropping a bare timestamp
239	            // where the design puts a state.
240	            project.status_kind = ProjectStatusKind::Unknown;
241	            // The recent list stamps "YYYY-MM-DD HH:MM:SS"; a status line does
242	            // not need the second.
243	            wxString when = wxString(item.get<std::wstring>(L"time", L""));
244	            if (when.length() == 19 && when[16] == ':')
245	                when = when.Left(16);
246	            if (!when.empty())
247	                project.status_text = std::string(wxString::Format(_L("Edited %s"), when).ToUTF8());
248	        }
249	        projects.push_back(std::move(project));
250	    }
251	    return projects;
252	}
253	
254	std::vector<PrinterEntry> OrcaHomeBackend::printers() const
255	{
256	    std::map<std::string, MachineObject*> machines;
257	    if (DeviceManager* devices = wxGetApp().getDeviceManager()) {
258	        for (const auto& entry : devices->get_my_machine_list())
259	            if (entry.second != nullptr)
260	                machines.emplace(entry.first, entry.second);
261	    }
262	
263	    // What each connected device has loaded, read once for the whole rail.
264	    // A connected device with nothing loaded has an empty entry: it is the
265	    // printer saying so, and the card believes it over what was remembered.
266	    std::map<std::string, std::vector<SpoolEntry>> loaded;
267	    if (!machines.empty())
268	        for (const PrinterSetup::DiscoveredPrinter& device : PrinterSetup::discover_printers())
269	            if (device.connected) {
270	                auto& spools = loaded[device.stable_id];
271	                for (const PrinterSetup::DiscoveredPrinter::Spool& spool : device.spools)
272	                    spools.push_back(SpoolEntry{spool.material, spool.colour});
273	            }
274	
275	    // Every card says something about its connection; one with nothing
276	    // verified says so in words, and draws no dot.
277	    const auto settle_connection = [](PrinterEntry& printer) {
278	        if (printer.connection_state != ConnectionState::None)
279	            return;
280	        printer.connection_text   = utf8(_L("Not connected"));
281	        printer.connection_kind   = "";
282	        printer.connection_action = "";
283	    };
284	
285	    // The printers the person added, each with the device it stands for when
286	    // that device is here. The device's own reading of the nozzle wins: a
287	    // printer whose hardware was changed says so.
288	    std::vector<PrinterEntry> printers;
289	    std::set<std::string>     represented;
290	    for (const Printers::NamedPrinter& named : Printers::named_printers()) {
291	        PrinterEntry printer;
292	        printer.id                = kNamedPrefix + named.name;
293	        printer.name              = named.name;
294	        printer.kind              = PrinterKind::Named;
295	        printer.can_open_settings = true;
296	        printer.can_rename        = true;
297	        printer.can_remove        = true;
298	        std::string model;
299	        if (const auto* preset = wxGetApp().preset_bundle->printers.find_preset(named.name, false, true)) {
300	            model = model_name(preset->config.opt_string("printer_model"));
301	            // A print host's address is saved only once the host has answered
302	            // (or typed into Orca's own settings dialog, which is not tested:
303	            // an accepted gap). Nothing here says whether it answers now.
304	            const std::string host = preset->config.opt_string("print_host");
305	            if (!host.empty()) {
306	                printer.connection_state   = ConnectionState::Connected;
307	                printer.connection_kind    = "host";
308	                printer.address            = host_address(host);
309	                printer.connection_text    = utf8(_L("Connected") + middle_dot() + wxString::FromUTF8(printer.address));
310	                printer.can_launch_monitor = true;
311	            }
312	        }
313	        double nozzle = named.nozzle;
314	        if (const auto found = machines.find(named.device_id); !named.device_id.empty() && found != machines.end()) {
315	            describe_device(*found->second, printer);
316	            if (printer.can_launch_monitor) {
317	                wxGetApp().app_config->set("jusprin_verified_connections", named.device_id, "true");
318	                if (const double reported = reported_nozzle(*found->second); reported > 0.)
319	                    nozzle = reported;
320	            }
321	            represented.insert(named.device_id);
322	        } else if (PrinterSetup::has_verified_printer_connection(named.device_id)) {
323	            // Connected before, and the app has not heard of the device since.
324	            printer.connection_state  = ConnectionState::Offline;
325	            printer.connection_text   = utf8(_L("Offline"));
326	            printer.connection_action = "reconnect";
327	        }
328	        settle_connection(printer);
329	        printer.model_text = model_text(model, nozzle);
330	        // A connected printer says what it holds; otherwise the spools the
331	        // person described for it stand in.
332	        if (const auto held = loaded.find(named.device_id); !named.device_id.empty() && held != loaded.end())
333	            printer.spools = held->second;
334	        else if (m_spools != nullptr)
335	            for (const Workspace::Spool& spool : m_spools->spools_for(named.name))
336	                printer.spools.push_back(SpoolEntry{filament_type(spool.filament_preset), spool.colour});
337	        printers.push_back(std::move(printer));
338	    }
339	
340	    // Devices no named printer stands for. Their name and binding are the
341	    // device's, so renaming and removing them are upstream's device dialogs,
342	    // offered where upstream's device list offers them.
343	    for (const auto& [id, machine] : machines) {
344	        if (represented.count(id) > 0)
345	            continue;
346	        PrinterEntry printer;
347	        printer.id         = kDevicePrefix + id;
348	        printer.name       = machine->get_dev_name();
349	        printer.kind       = PrinterKind::Device;
350	        printer.can_rename = !machine->is_lan_mode_printer() && machine->is_online();
351	        printer.can_remove = !machine->is_lan_mode_printer();
352	        describe_device(*machine, printer);
353	        settle_connection(printer);
354	        printer.model_text = model_text(model_name({}, machine->printer_type), reported_nozzle(*machine));
355	        if (const auto held = loaded.find(id); held != loaded.end())
356	            printer.spools = held->second;
357	        printers.push_back(std::move(printer));
358	    }
359	    return printers;
360	}
361	
362	void OrcaHomeBackend::open_project(const std::string& project_id)
363	{
364	    if (project_id.empty())
365	        return;
366	    const size_t                 wanted = static_cast<size_t>(std::stoul(project_id));
367	    boost::property_tree::wptree recent;
368	    m_frame.get_recent_projects(recent, 0);
369	    size_t at = 0;
370	    for (const auto& node : recent) {
371	        if (at++ != wanted)
372	            continue;
373	        const wxString path(node.second.get<std::wstring>(L"path", L""));
374	        m_frame.open_recent_project(wanted, path);
375	        // Opening a project is a move to the workspace, but only if it opens.
376	        // open_recent_project queues the load behind can_load_project(), which
377	        // asks about unsaved changes and abandons the load when the answer is
378	        // Cancel. Queueing the move behind that lambda -- CallAfter is FIFO --
379	        // and confirming the project that is now open is the one that was
380	        // asked for keeps a cancelled open on Home instead of navigating out
381	        // from under it.
382	        m_frame.CallAfter([this, path] {
383	            Plater* plater = wxGetApp().plater();
384	            if (plater != nullptr && wxFileName(plater->get_project_filename()).SameAs(wxFileName(path)))
385	                m_frame.select_tab(size_t(MainFrame::tp3DEditor));
386	        });
387	        return;
388	    }
389	}
390	
391	void OrcaHomeBackend::new_project()
392	{
393	    Plater* plater = wxGetApp().plater();
394	    if (plater == nullptr)
395	        return;
396	    // Cancelling the unsaved-changes question leaves the old project in place,
397	    // so it leaves Home in place too.
398	    if (plater->new_project() != wxID_CANCEL)
399	        m_frame.select_tab(size_t(MainFrame::tp3DEditor));
400	}
401	
402	void OrcaHomeBackend::import_model()
403	{
404	    Plater* plater = wxGetApp().plater();
405	    if (plater == nullptr)
406	        return;
407	    // add_model imports into the project that is open and runs its own modal
408	    // file dialog. It returns void, so the object count before and after is
409	    // what says whether anything arrived: cancelling the dialog leaves Home
410	    // where it was, as cancelling New does.
411	    const size_t before = plater->model().objects.size();
412	    plater->add_model();
413	    if (plater->model().objects.size() != before)
414	        m_frame.select_tab(size_t(MainFrame::tp3DEditor));
415	}
416	
417	void OrcaHomeBackend::launch_monitor(const std::string& printer_id)
418	{
419	    // A named printer is monitored through the device it stands for.
420	    std::string device_id = strip(printer_id, kDevicePrefix).value_or(std::string());
421	    if (const auto name = strip(printer_id, kNamedPrefix))
422	        for (const Printers::NamedPrinter& named : Printers::named_printers())
423	            if (named.name == *name)
424	                device_id = named.device_id;
425	    if (const auto name = strip(printer_id, kNamedPrefix); name && device_id.empty()) {
426	        open_printer_window(*name);
427	        return;
428	    }
429	    if (device_id.empty())
430	        return; // the card changed under the click; the refreshed rail says so
431	    // Upstream's own path to the Monitor, as the device popup and the
432	    // multi-machine page use. Selecting the tab and the machine by hand
433	    // instead left Home on screen: jump_to_monitor also guards on the Monitor
434	    // panel existing and selects the machine inside it. Upstream may still
435	    // decline the switch -- it vetoes the Monitor tab when the network plugin
436	    // is missing -- and that refusal is upstream's to make.
437	    m_frame.jump_to_monitor(device_id);
438	}
439	
440	void OrcaHomeBackend::open_printer_window(const std::string& name)
441	{
442	    const Preset* preset = wxGetApp().preset_bundle->printers.find_preset(name, false, true);
443	    if (preset == nullptr || preset->config.opt_string("print_host").empty())
444	        return; // the card changed under the click; the refreshed rail says so
445	    // One window per printer: a second click brings it back rather than
446	    // opening another beside it.
447	    if (auto open = m_printer_windows.find(name); open != m_printer_windows.end() && open->second) {
448	        open->second->Iconize(false);
449	        open->second->Raise();
450	        return;
451	    }
452	    m_printer_windows[name] = new PrinterWindow(name, preset->config);
453	}
454	
455	OrcaHomeBackend::~OrcaHomeBackend()
456	{
457	    // The windows have no parent, so they would outlive the app's main
458	    // window; they go with it, as the Device tab they stand in for does.
459	    for (auto& [name, window] : m_printer_windows)
460	        if (window)
461	            window->Destroy();
462	}
463	
464	void OrcaHomeBackend::add_printer()
465	{
466	    // The conversation replaces the printers column in place; the shell draws
467	    // it and owns the session.
468	    if (m_open_conversation)
469	        m_open_conversation({}, false);
470	}
471	
472	std::string OrcaHomeBackend::open_printer_settings(const std::string& printer_id)
473	{
474	    const auto name = strip(printer_id, kNamedPrefix);
475	    if (!name)
476	        return gone();
477	    // "Printer settings…" opens that printer's own conversation, where "Set
478	    // it up myself" still leads to OrcaSlicer's settings window.
479	    if (m_open_conversation)
480	        m_open_conversation(*name, false);
481	    return {};
482	}
483	
484	std::string OrcaHomeBackend::connect_printer(const std::string& printer_id)
485	{
486	    const auto name = strip(printer_id, kNamedPrefix);
487	    if (!name)
488	        return gone();
489	    const auto saved = Printers::named_printers();
490	    if (std::none_of(saved.begin(), saved.end(), [&](const auto& printer) { return printer.name == *name; }))
491	        return gone();
492	    if (m_open_conversation)
493	        m_open_conversation(*name, true);
494	    return {};
495	}
496	
497	std::string OrcaHomeBackend::rename_printer(const std::string& printer_id, const std::string& new_name)
498	{
499	    Plater* plater = wxGetApp().plater();
500	    if (plater == nullptr)
501	        return gone();
502	    if (const auto name = strip(printer_id, kNamedPrefix))
503	        return utf8(Printers::rename_named_printer(*plater, m_spools, *name, new_name));
504	    // A device keeps its own name. Upstream's dialog, as the device list
505	    // opens it, validates and sends the new one.
506	    MachineObject* machine = my_machine(strip(printer_id, kDevicePrefix).value_or(std::string()));
507	    if (machine == nullptr)
508	        return gone();
509	    EditDevNameDialog dialog(plater);
510	    dialog.set_machine_obj(machine);
511	    dialog.ShowModal();
512	    return {};
513	}
514	
515	std::string OrcaHomeBackend::remove_printer(const std::string& printer_id)
516	{
517	    Plater* plater = wxGetApp().plater();
518	    if (plater == nullptr)
519	        return gone();
520	    if (const auto name = strip(printer_id, kNamedPrefix))
521	        return utf8(Printers::remove_named_printer(*plater, m_spools, *name));
522	    // Removing a device unbinds it from the account, through upstream's
523	    // dialog, which confirms and reports for itself, as the device list does.
524	    const std::string device_id = strip(printer_id, kDevicePrefix).value_or(std::string());
525	    MachineObject*    machine   = my_machine(device_id);
526	    if (machine == nullptr)
527	        return gone();
528	    UnBindMachineDialog dialog(plater);
529	    dialog.update_machine_info(machine);
530	    if (dialog.ShowModal() == wxID_OK)
531	        wxGetApp().getDeviceManager()->set_selected_machine("");
532	    return {};
533	}
534	
535	}}}} // namespace Slic3r::GUI::JusPrin::Home
