477	HeaderMenu::HeaderMenu(wxWindow* parent, const ShellTheme& theme, bool dark, std::vector<HeaderMenuItem> items)
478	    : PopupWindow(parent, wxBORDER_NONE | wxPU_CONTAINS_CONTROLS | wxFRAME_SHAPED)
479	    , m_theme(theme)
480	    , m_dark(dark)
481	{
482	    SetName("Header menu");
483	    SetBackgroundStyle(wxBG_STYLE_PAINT);
484	    const auto palette = theme.palette(dark);
485	    const int radius = theme.metrics().popover.radius;
486	    Bind(wxEVT_PAINT,[this,palette,radius](wxPaintEvent&) {
487	        wxAutoBufferedPaintDC dc(this);
488	        dc.SetBackground(wxBrush(palette.surface_raised)); dc.Clear();
489	        dc.SetPen(wxPen(palette.border_subtle)); dc.SetBrush(wxBrush(palette.surface_raised));
490	        dc.DrawRoundedRectangle(GetClientRect().Deflate(1),FromDIP(radius));
491	    });
492	    build(std::move(items));
493	    Bind(wxEVT_CHAR_HOOK,&HeaderMenu::on_key,this);
494	    // wxPopupFocusHandler forwards CHAR (not CHAR_HOOK) and dismisses an
495	    // unhandled key on macOS. Handle that native route as well.
496	    Bind(wxEVT_CHAR,&HeaderMenu::on_key,this);
497	}
498	
499	void HeaderMenu::build(std::vector<HeaderMenuItem> items)
500	{
501	    const auto palette = m_theme.palette(m_dark);
502	    const PopoverMetrics& popover = m_theme.metrics().popover;
503	    const MenuRowMetrics& menu_row = m_theme.metrics().menu_row;
504	    // A rebuild replaces every row, so drop the old selection rather than
505	    // leaving an index pointing into a destroyed vector.
506	    m_selected = -1;
507	    m_items.clear();
508	    if (auto* old = GetSizer()) {
509	        old->Clear(true);
510	        SetSizer(nullptr, true);
511	    }
512	    m_header = nullptr;
513	
514	    auto* sizer = new wxBoxSizer(wxVERTICAL);
515	    sizer->AddSpacer(FromDIP(popover.padding_y));
516	    int placed_rows = 0;
517	    bool after_row = false; // the row gap sits only between two consecutive rows
518	    auto place_header = [&] {
519	        if (!m_header_builder || m_header != nullptr) return;
520	        m_header = m_header_builder(this);
521	        if (m_header) sizer->Add(m_header,0,wxEXPAND | wxLEFT | wxRIGHT | wxBOTTOM,FromDIP(8));
522	        after_row = false;
523	    };
524	    if (m_header_after_rows == 0) place_header();
525	    for (auto& item : items) {
526	        if (placed_rows == m_header_after_rows) place_header();
527	        if (item.separator) {
528	            auto* line = new wxStaticLine(this);
529	            line->SetForegroundColour(palette.border_subtle);
530	            sizer->Add(line,0,wxEXPAND | wxLEFT | wxRIGHT | wxTOP | wxBOTTOM,FromDIP(menu_row.side_inset));
531	            after_row = false;
532	        }
533	        // A separator-only entry carries no caption of its own.
534	        if (item.title && item.label.empty()) continue;
535	        if (item.title) {
536	            // Eyebrow: a caption, not a row. It takes no focus, no hover, and
537	            // no keyboard stop, so arrow keys skip straight over it.
538	            auto* caption = new wxStaticText(this,wxID_ANY,item.label);
539	            caption->SetFont(m_theme.font(TextRole::Metadata));
540	            caption->SetForegroundColour(palette.text_secondary);
541	            caption->SetBackgroundColour(palette.surface_raised);
542	            sizer->Add(caption,0,wxEXPAND | wxLEFT | wxRIGHT | wxTOP | wxBOTTOM,FromDIP(8));
543	            ++placed_rows;
544	            after_row = false;
545	            continue;
546	        }
547	        auto* button = new HeaderButton(this,m_theme,HeaderStyle::Menu,item.label,item.icon);
548	        button->SetName(item.label);
549	        item.decoration.detail = item.decoration.detail.empty() ? item.detail : item.decoration.detail;
550	        button->set_decoration(item.decoration);
551	        button->set_dark(m_dark);
552	        button->set_row_action(item.row_action);
553	        button->Enable(item.enabled);
554	        if (item.invoke_row_action)
555	            button->Bind(wxEVT_MENU,[this,action=std::move(item.invoke_row_action)](wxCommandEvent&) {
556	                // Like keeps_open rows, this rebuilds the popup's own contents.
557	                // MSVC binds 'this' in a nested lambda's init-capture to the
558	                // enclosing closure, not to HeaderMenu, so name the menu first.
559	                auto* menu = this;
560	                CallAfter([self=wxWeakRef<wxWindow>(menu),action] { if (self) action(); });
561	            });
562	        m_items.push_back(button);
563	        button->Bind(wxEVT_ENTER_WINDOW,[this,index=int(m_items.size()-1)](wxMouseEvent& e) {
564	            if (m_items[index]->IsEnabled()) select_item(index);
565	            e.Skip();
566	        });
567	        if (after_row) sizer->AddSpacer(FromDIP(popover.row_gap));
568	        sizer->Add(button,0,wxEXPAND | wxLEFT | wxRIGHT,FromDIP(menu_row.side_inset));
569	        ++placed_rows;
570	        after_row = true;
571	        button->Bind(wxEVT_BUTTON,[this,owner=wxWeakRef<wxWindow>(GetParent()),invoke=std::move(item.invoke),
572	                                   keeps_open=item.keeps_open](wxCommandEvent&) {
573	            if (!invoke) return;
574	            if (keeps_open) {
575	                // The handler rebuilds this menu's rows, which destroys the
576	                // button currently delivering this event. Defer past it.
577	                // MSVC binds 'this' in a nested lambda's init-capture to the
578	                // enclosing closure, not to HeaderMenu, so name the menu first.
579	                auto* menu = this;
580	                CallAfter([self=wxWeakRef<wxWindow>(menu),invoke] { if (self) invoke(); });
581	                return;
582	            }
583	            close();
584	            if (owner) owner->CallAfter([owner,invoke] { if (owner) invoke(); });
585	        });
586	    }
587	    place_header(); // a step with fewer rows than requested still gets its view
588	    sizer->AddSpacer(FromDIP(popover.padding_y));
589	    SetSizerAndFit(sizer);
590	    // The first build fixes the width; later rebuilds keep it so swapping to
591	    // the search view does not make the popup jump under the pointer.
592	    if (m_width == 0)
593	        m_width = std::clamp(GetSize().x,FromDIP(280),FromDIP(420));
594	    SetSize(wxSize(m_width,GetSize().y));
595	    Layout();
596	#if defined(__WXOSX__) || defined(__WXMSW__)
597	    // Preserve the actual rounded silhouette (and the compositor's popup
598	    // shadow), rather than painting a rounded border into a square window.
599	    auto outline = wxGraphicsRenderer::GetDefaultRenderer()->CreatePath();
600	    outline.AddRoundedRectangle(0,0,GetSize().x,GetSize().y,FromDIP(popover.radius));
601	    SetShape(outline);
602	#endif
603	}
604	
605	void HeaderMenu::set_header_builder(std::function<wxWindow*(wxWindow*)> builder, int after_rows)
606	{
607	    m_header_builder    = std::move(builder);
608	    m_header_after_rows = after_rows;
609	}
610	
611	void HeaderMenu::replace_items(std::vector<HeaderMenuItem> items)
612	{
613	    build(std::move(items));
614	    reposition();
615	}
616	
617	void HeaderMenu::on_key(wxKeyEvent& e)
618	{
619	    const int key = e.GetKeyCode();
620	    if (key == WXK_ESCAPE || key == WXK_TAB) { close(); return; }
621	    if (key == WXK_RETURN || key == WXK_NUMPAD_ENTER || key == WXK_SPACE) {
622	        if (auto* button = selected_item()) {
623	            wxCommandEvent click(wxEVT_BUTTON,button->GetId());
624	            click.SetEventObject(button);
625	            button->ProcessWindowEvent(click);
626	            return;
627	        }
628	        e.Skip();
629	        return;
630	    }
631	    if (key == WXK_RIGHT) {
632	        // The keyboard equivalent of the hover-revealed row action.
633	        if (auto* button = selected_item(); button != nullptr && button->has_row_action()) {
634	            button->invoke_row_action();
635	            return;
636	        }
637	        e.Skip();
638	        return;
639	    }
640	    if (key != WXK_UP && key != WXK_DOWN && key != WXK_HOME && key != WXK_END) { e.Skip(); return; }
641	    if (m_items.empty()) { e.Skip(); return; }
642	    int index = m_selected;
643	    // With no row selected, Down starts before the first and Up wraps back
644	    // from the last -- the same offset trick Home and End use below.
645	    if (index < 0) index = key == WXK_UP ? 0 : -1;
646	    if (key == WXK_HOME) index = -1;
647	    if (key == WXK_END) index = 0;
648	    const int step = key == WXK_UP || key == WXK_END ? -1 : 1;
649	    for (size_t n=0;n<m_items.size();++n) {
650	        index = (index+step+int(m_items.size()))%int(m_items.size());
651	        if (m_items[index]->IsEnabled()) { select_item(index); break; }
652	    }
653	}
654	
655	void HeaderMenu::open(HeaderButton& anchor)
656	{
657	    m_anchor = &anchor;
658	    anchor.set_open(true);
659	    reposition();
660	    Popup();
661	    Raise();
662	    // Like an owner-drawn list, the popup owns its keyboard selection. Cocoa
663	    // can deliver keys to the popup without assigning focus to a child view.
664	    // A mouse-opened menu highlights nothing until the pointer or an arrow key
665	    // picks a row; a keyboard-opened one starts on the first row so a keyboard
666	    // user has a visible starting point. Arrows work from either state.
667	    if (anchor.activated_by_keyboard())
668	        for (size_t i=0;i<m_items.size();++i) if (m_items[i]->IsEnabled()) { select_item(int(i)); break; }
669	}
670	
671	void HeaderMenu::reposition()
672	{
673	    if (!m_anchor) return;
674	    Position(m_anchor->ClientToScreen(wxPoint(m_anchor->GetSize().x-GetSize().x,m_anchor->GetSize().y+FromDIP(4))),wxSize(0,0));
675	}
676	
677	void HeaderMenu::select_item(int index)
678	{
679	    if (m_selected >= 0 && m_selected < int(m_items.size())) m_items[m_selected]->set_menu_selected(false);
680	    m_selected = index;
681	    m_items[index]->set_menu_selected(true);
682	}
683	
684	void HeaderMenu::OnDismiss()
685	{
686	    if (m_closed) return; // Native dismissal and an explicit Escape can coincide.
687	    m_closed = true;
688	    if (m_anchor) { m_anchor->set_open(false); m_anchor->SetFocus(); }
689	    if (m_dismissed) m_dismissed();
690	    Destroy();
691	}
692	
693	void HeaderMenu::close() { Dismiss(); OnDismiss(); }
694	
695	} // namespace Slic3r::GUI::JusPrin
