25	// The alias Orca shows in the sidebar: the preset's alias, with the
26	// "@<printer>" qualifier trimmed the way StatusRow already trims it.
27	wxString display_alias(const Preset& preset)
28	{
29	    wxString alias = wxString::FromUTF8(preset.alias.empty() ? preset.name : preset.alias);
30	    alias = alias.BeforeFirst('@');
31	    alias.Trim();
32	    return alias;
33	}
