56	PrinterInfo current_printer()
57	{
58	    PrinterInfo info;
59	    const PresetBundle* presets = wxGetApp().preset_bundle;
60	    if (presets == nullptr)
61	        return info;
62	    const Preset& printer = presets->printers.get_edited_preset();
63	    info.preset_name = printer.name;
64	    // A named printer is called what the person called it; a system profile
65	    // is only a model.
66	    info.nickname = wxString::FromUTF8(Printers::is_named_printer(printer) ? printer.name
67	                                                                            : printer.config.opt_string("printer_model"));
68	    if (info.nickname.empty()) {
69	        info.nickname = wxString::FromUTF8(printer.label(false));
70	        // Custom profiles often encode the nozzle in their display name.
71	        const auto nozzle_suffix = info.nickname.Find(" nozzle");
72	        if (nozzle_suffix != wxNOT_FOUND) info.nickname = info.nickname.Left(nozzle_suffix).BeforeLast(' ');
73	    }
74	    if (const auto* nozzle = printer.config.option<ConfigOptionFloats>("nozzle_diameter"); nozzle && !nozzle->values.empty()) {
75	        info.nozzle         = nozzle->values.front();
76	        info.extruder_count = nozzle->values.size();
77	    }
78	    info.valid = true;
79	    return info;
80	}
