107	std::vector<BedTypeChoice> bed_types()
108	{
109	    std::vector<BedTypeChoice> choices;
110	    auto* plater = wxGetApp().plater();
111	    if (plater == nullptr)
112	        return choices;
113	
114	    // Orca filters the list per printer model; read its filtered list rather
115	    // than enumerating the BedType enum, or the menu would offer plates this
116	    // machine does not have.
117	    const std::vector<BedType>& supported = plater->sidebar().get_cur_combox_bed_types();
118	    if (supported.size() < 2)
119	        return choices;
120	    const BedType current = plater->sidebar().get_cur_select_bed_type();
121	
122	    const ConfigOptionDef* definition = print_config_def.get("curr_bed_type");
123	    for (BedType type : supported) {
124	        wxString label;
125	        if (definition != nullptr) {
126	            // enum_values is 0-based over the labels that follow btDefault.
127	            const int index = int(type) - 1;
128	            if (index >= 0 && index < int(definition->enum_labels.size()))
129	                label = _(definition->enum_labels[index]);
130	        }
131	        if (label.empty())
132	            label = wxString::Format("%d", int(type));
133	        choices.push_back({int(type), label, type == current});
134	    }
135	    return choices;
