138	std::vector<FilamentInfo> compatible_filaments()
139	{
140	    std::vector<FilamentInfo> filaments;
141	    const PresetBundle* presets = wxGetApp().preset_bundle;
142	    if (presets == nullptr)
143	        return filaments;
144	    for (const Preset& preset : presets->filaments) {
145	        // is_compatible is maintained by PresetBundle::update_compatible; the
146	        // compatibility rule is never re-derived here.
147	        if (!preset.is_visible || !preset.is_compatible || preset.is_default)
148	            continue;
149	        FilamentInfo info;
150	        info.preset_name = preset.name;
151	        info.alias       = display_alias(preset);
152	        info.vendor      = filament_vendor(preset);
153	        info.material    = option_string(preset.config, "filament_type");
154	        info.valid       = true;
155	        filaments.push_back(std::move(info));
156	    }
157	    return filaments;
