160	PrinterConnection printer_connection()
161	{
162	    PrinterConnection connection;
163	    // Non-const: use_bbl_network() is not a const member on PresetBundle.
164	    PresetBundle* presets = wxGetApp().preset_bundle;
165	    // Only the Bambu network path reports a live machine state. Every other
166	    // print host is "not connected" here, which is a statement about what
167	    // JusPrin can observe, not a claim about the machine.
168	    if (presets == nullptr || !presets->use_bbl_network())
169	        return connection;
170	    auto* devices = wxGetApp().getDeviceManager();
171	    if (devices == nullptr)
172	        return connection;
173	    MachineObject* machine = devices->get_selected_machine();
174	    if (machine == nullptr)
175	        return connection;
176	    connection.monitor_available = true;
177	    if (!machine->is_connected())
178	        connection.state = ConnectionState::Offline;
179	    else if (machine->is_in_printing())
180	        connection.state = ConnectionState::Printing;
