namespace Slic3r { namespace GUI { namespace JusPrin {

class ShellTheme;

namespace Workspace {
class SpoolStore;
}

namespace Home {

class HomeWebView : public wxPanel
{
public:
    HomeWebView(wxWindow* parent, const ShellTheme& theme, MainFrame& frame, Workspace::SpoolStore* spools);
    ~HomeWebView() override;

    void apply_appearance(bool dark);
    // Re-reads the recent-project list and the device state. The shell calls
    // this when Home becomes visible: the gallery is a view of state that
    // changes while another screen is in front. `added` leads the column
    // with a successful Add and sends its receipt, for this one refresh.
    void refresh(const std::string& added = {});
    // While live, the printer cards follow the devices, profiles and spools
    // they describe without the person leaving Home: once a second -- the
    // Monitor's own refresh rate -- the rail is re-read and sent only when a
    // card changed. Polled, because upstream announces no device update, and
    // a printer going Offline is time passing rather than a message. The
    // shell makes Home live exactly while it is the selected screen.
        return {};
    return wxFileSystem::FileNameToURL(wxFileName(wxString::FromUTF8(page.string())));
}

} // namespace

HomeWebView::HomeWebView(wxWindow* parent, const ShellTheme& theme, MainFrame& frame, Workspace::SpoolStore* spools)
    : wxPanel(parent, wxID_ANY), m_theme(theme), m_live_timer(this)
{
    Bind(wxEVT_TIMER, &HomeWebView::on_live_tick, this, m_live_timer.GetId());
    m_backend = std::make_unique<OrcaHomeBackend>(frame, spools);
    m_host    = std::make_unique<HomeHost>(*m_backend, [this](const std::string& envelope) {
        if (m_webview == nullptr)
            return;
        wxString script = "window.__jusprinBridge && window.__jusprinBridge.deliver(";
        script += wxString::FromUTF8(envelope);
        script += ")";

