#pragma once

// The one route from the printer panel to Orca. Every read comes from an
// existing owner -- the packaged catalogue, Bambu's device list, the printer
// preset collection, the spool store -- and writes reuse the preset, device,
// networking and print-host owners rather than copying their mechanisms.

#include "PrinterBackend.hpp"
#include "PrinterCatalog.hpp"
#include <atomic>
#include <chrono>
#include <memory>

namespace Slic3r::GUI { class Plater; }
namespace Slic3r::GUI::JusPrin::Workspace { class SpoolStore; }

namespace Slic3r::GUI::JusPrin::PrinterSetup {

class OrcaPrinterBackend : public IPrinterBackend
{
public:
    // `spools` is the app-level store the rest of the shell already shares;
    // without one this backend reports a printer's spools as unknown and
    // refuses to change them.
    OrcaPrinterBackend(Plater& plater, PrinterCatalog catalog, Workspace::SpoolStore* spools);

    const std::vector<CatalogPrinter>& catalog() const override { return m_models; }
    std::vector<DiscoveredPrinter> network_printers() const override;
    std::vector<SavedPrinter>      saved_printers() const override;


private:
    const CatalogPrinter* model_of(const std::string& printer_name) const;

    Plater&                     m_plater;
    PrinterCatalog              m_catalog;
    Workspace::SpoolStore*      m_spools{nullptr};
    // One entry per model, built once from the catalogue's per-variant
    // candidates: the panel proposes printers, and a nozzle is a fact about
    // the printer rather than a printer of its own.
    std::vector<CatalogPrinter> m_models;
    struct ConnectionAttempt {
#pragma once

// What the printer conversation is allowed to know and do about printers.
//
// A printer is app-level, not project-level, so this follows Home rather than
// the workspace contract: the surface owns a narrow interface, and one Orca
// implementation behind it calls the existing owners -- PrinterCatalog,
// PrinterDiscovery, Printers::, SetupCommands::, SpoolStore. GUI-free and
// Orca-free so the conversation can be tested without either.

#include "PrinterSetupTypes.hpp"

namespace Slic3r::GUI::JusPrin::PrinterSetup {

// One spool as a printer reports it or as this app remembers it.
struct PrinterSpool
{
    std::string name;
    std::string material;
    std::string colour; // "#RRGGBB", empty when unknown
};

// A printer already saved in this app: an Orca user printer profile, with the
// facts it was set up with.
struct SavedPrinter
{
    std::string               name;
    std::string               device_id;
    std::string               model;        // display model name
    std::string               model_id;     // profile model id
    std::string               vendor_id;
    std::string               picture;      // cover image path, may be empty
    double                    nozzle{0.};
    std::vector<double>       nozzles;      // sizes this model ships
    std::string               plate;        // untranslated plate name
    std::string               ams;          // "AMS lite", "AMS", or empty
    std::vector<PrinterSpool> spools;
    std::string               activity;     // offline, idle, printing, or empty
    bool                      connected{false};
};
#include <memory>
#include <string>
#include <vector>

namespace Slic3r::GUI { class Plater; }
namespace Slic3r::GUI::JusPrin::Workspace { class SpoolStore; }

namespace Slic3r::GUI::JusPrin::PrinterSetup {

class PrinterPanel : public wxPanel, private IConversationHost
{
public:
    struct Callbacks
    {
        // Back, and everything else that ends the session.
        std::function<void()> closed;
        // A printer was saved or changed; Home's list is out of date.
        // `added` names a printer this session just added, or is empty.
        std::function<void(const std::string& added)> printers_changed;
        // The person set the agent up in here, so the rest of the shell has
        // to look again at how it is configured.
        std::function<void()> agent_configured;
    };

    PrinterPanel(wxWindow*              parent,
                 const ShellTheme&      theme,
                 bool                   dark,
                 Workspace::IWorkspace& workspace,
                 Plater&                plater,
                 Workspace::SpoolStore* spools,
                 Callbacks              callbacks);
    ~PrinterPanel() override;

    // Opens a fresh session. Opening it again replaces the session: no
    // history carries over, by design.
    void open(ConversationMode mode, const std::string& printer_name = {});
} // namespace

PrinterPanel::PrinterPanel(wxWindow*              parent,
                           const ShellTheme&      theme,
                           bool                   dark,
                           Workspace::IWorkspace& workspace,
                           Plater&                plater,
                           Workspace::SpoolStore* spools,
                           Callbacks              callbacks)
    : wxPanel(parent, wxID_ANY)
    , m_theme(theme)
    , m_dark(dark)
    , m_workspace(workspace)
    , m_callbacks(std::move(callbacks))
    , m_backend(std::make_unique<OrcaPrinterBackend>(plater, PrinterCatalog::load(Slic3r::resources_dir()), spools))
    // The cast is made here, inside the class, because this panel keeps its
    // conversation-host side private.
    , m_conversation(new PrinterConversation(*m_backend, static_cast<IConversationHost&>(*this)))
    , m_pump(this, kPumpTimerId)
            if (candidate.model_id == found->model_id && nozzle_of(candidate.variant) == *request.nozzle)
                variant = &candidate;
        if (variant == nullptr)
            return found->model.empty() ? std::string("This printer does not come with that nozzle size.") :
                                          "The " + found->model + " does not come with that nozzle size.";
        const wxString problem = Printers::change_named_printer_nozzle(m_plater, request.name, variant->preset_name);
        if (!problem.empty())
            return problem.ToStdString();
    }

    if (request.spools) {
        if (m_spools == nullptr)
            return "This app cannot record spools yet.";
        for (const Workspace::Spool& spool : m_spools->spools_for(request.name))
            m_spools->remove(spool.id);
        for (const PrinterSpool& spool : *request.spools) {
            Workspace::Spool record;
            record.printer_preset  = request.name;
            record.filament_preset = spool.material;
            record.name            = spool.name;
            record.colour          = spool.colour;
            m_spools->add(std::move(record));
        }
    }

    for (const SavedPrinter& saved : saved_printers())
        if (saved.name == request.name)
            changed = saved;
    return {};
}

std::string OrcaPrinterBackend::remove_printer(const std::string& name)
{
    return std::string(Printers::remove_named_printer(m_plater, m_spools, name).ToUTF8());
}

