2825	    // The selectable rows of an open menu, in order. Rows are named by their
2826	    // full label, which the paint-time ellipsis never shortens.
2827	    std::vector<std::string> menu_row_names(HeaderMenu* menu) const
2828	    {
2829	        std::vector<std::string> names;
2830	        for (auto* child : menu->GetChildren())
2831	            if (auto* button = dynamic_cast<HeaderButton*>(child)) names.push_back(ui_text(button->GetName()));
2832	        return names;
2833	    }
2834	
2835	    // "Generic preset…" must narrow the list by the vendor the profile
2836	    // declares. The earlier implementation instead typed "Generic" into the
2837	    // search box and re-ran the substring search, which matched any preset
2838	    // whose name happened to read "generic", missed generic presets named
2839	    // otherwise, and left a word in a field the person never typed into. Each
2840	    // of those three is checked here, so a regression to text matching fails
2841	    // rather than passing on a list that happens to look similar.
2842	    void verify_generic_preset_filter()
2843	    {
2844	        installed_shell()->status_row()->open_spool_menu();
2845	        auto* menu = visible_header_menu();
2846	        check(menu != nullptr, "spool_menu_opens_for_the_generic_filter");
2847	        if (menu == nullptr) return;
2848	
2849	        menu = click_menu_row(menu, ui_name("Other spool…"));
2850	        check(menu != nullptr, "other_spool_step_opens");
2851	        if (menu == nullptr) return;
2852	        const std::size_t unfiltered_rows = menu_row_names(menu).size();
2853	
2854	        menu = click_menu_row(menu, ui_name("Generic preset…"));
2855	        check(menu != nullptr, "generic_preset_step_opens");
2856	        if (menu == nullptr) return;
2857	
2858	        wxTextCtrl* field = nullptr;
2859	        for (auto* child : menu->GetChildren())
2860	            if (auto* text = dynamic_cast<wxTextCtrl*>(child); text && field == nullptr) field = text;
2861	        check(field != nullptr && field->GetValue().empty(), "generic_step_leaves_the_search_field_empty");
2862	
2863	        const std::vector<std::string> names = menu_row_names(menu);
2864	        check(!names.empty() && names.front().find("GENERIC") != std::string::npos,
2865	              "generic_step_title_says_the_list_is_filtered");
2866	        check(names.size() < unfiltered_rows, "generic_step_shortens_the_list");
2867	
2868	        // The listed rows must be exactly the compatible presets whose vendor
2869	        // is Generic -- no branded preset admitted, no generic one dropped.
2870	        std::vector<std::string> listed, expected;
2871	        for (std::size_t i = 1; i < names.size(); ++i)
2872	            if (names[i] != "Import a preset file…") listed.push_back(names[i]);
2873	        std::string branded; // an alias the vendor test must have excluded
2874	        for (const auto& filament : SetupCommands::compatible_filaments()) {
2875	            if (filament.vendor == SetupCommands::kGenericVendor) expected.push_back(ui_text(filament.alias));
2876	            else if (branded.empty()) branded = ui_text(filament.alias);
2877	        }
2878	        std::sort(listed.begin(), listed.end());
2879	        std::sort(expected.begin(), expected.end());
2880	        check(!expected.empty(), "the_printer_has_generic_filament_presets");
2881	        check(listed == expected, "generic_step_lists_exactly_the_generic_vendor_presets");
2882	        check(!branded.empty() && std::find(listed.begin(), listed.end(), branded) == listed.end(),
2883	              "generic_step_drops_a_branded_preset");
2884	
2885	        // Back must reach the full list again, not leave the menu.
2886	        menu = click_menu_row(menu, ui_name(names.front()));
2887	        check(menu != nullptr && menu_row_names(menu).size() == unfiltered_rows,
2888	              "generic_step_returns_to_the_full_list");
2889	        if (menu == nullptr) return;
2890	        menu->close();
2891	        wxYield();
2892	        check(!chip_half_open(), "generic_step_dismisses_cleanly");
2893	    }
2894	
2895	    void verify_header_setup(Preset::Type type)
2896	    {
2897	        // The printer half opens the printer menu; the spool half's row menu
2898	        // is where Filament settings… now lives, one step in from the list.
2899	        if (type == Preset::TYPE_PRINTER) {
2900	            // Printer settings… talks about the selected printer in the
2901	            // printer conversation on Home. Only a printer saved under a name
2902	            // can be changed there, so one is saved from the fixture's own
2903	            // profile and selected for the length of the check.
2904	            m_header_setup_restore_printer = wxGetApp().preset_bundle->printers.get_selected_preset_name();
2905	            m_header_setup_printer         = Printers::add_named_printer(*m_plater, "Header Printer", {});
2906	            check(SetupCommands::current_printer().nickname.ToStdString() == m_header_setup_printer,
2907	                  "header_setup_named_printer_selected");
2908	            installed_shell()->status_row()->open_printer_menu();
