318	wxWindow* FilamentMenu::build_colour_row(const Ptr& self, wxWindow* parent, View view)
319	{
320	    const std::size_t slot = view.slot.value_or(0);
321	    const auto& palette = self->m_theme.palette(self->m_dark);
322	    auto*       panel   = new wxPanel(parent);
323	    panel->SetBackgroundColour(palette.surface_raised);
324	    auto* column = new wxBoxSizer(wxVERTICAL);
325	
326	    auto* caption = new wxStaticText(panel, wxID_ANY, _L("COLOUR"));
327	    style_label(*caption, self->m_theme, TextRole::Metadata, palette.text_secondary);
328	    column->Add(caption, 0, wxBOTTOM, panel->FromDIP(4));
329	
330	    const auto     slots   = SetupCommands::filament_slots();
331	    const wxColour current = slot < slots.size() ? wxColour(slots[slot].colour) : wxColour();
332	    // The slot's own colour first, then the saved ones, each once. No names:
333	    // the app holds a colour as a value and nothing more.
334	    std::vector<wxColour> colours;
335	    if (current.IsOk()) colours.push_back(current);
336	    for (const wxColour& saved : SetupCommands::saved_colours())
337	        if (std::find(colours.begin(), colours.end(), saved) == colours.end())
338	            colours.push_back(saved);
339	    if (colours.size() > kColourCells - 1) colours.resize(kColourCells - 1);
340	
341	    auto* grid = new wxGridSizer(int(kColoursPerRow), panel->FromDIP(4), panel->FromDIP(4));
342	    for (const wxColour& colour : colours) {
343	        const bool chosen = colour == current;
344	        auto* cell = new ColourCell(panel, self->m_theme, palette, colour, chosen, [self, view, colour] {
345	            // Colour only: the plan does not change, so the visit records
346	            // nothing for the thread.
347	            if (self->m_host.plater) SetupCommands::set_filament_colour(*self->m_host.plater, view.slot.value_or(0), colour);
348	            if (self->m_host.changed) self->m_host.changed();
349	            show(self, view);
350	        });
351	        cell->SetName(colour.GetAsString(wxC2S_HTML_SYNTAX));
352	        cell->SetToolTip(colour.GetAsString(wxC2S_HTML_SYNTAX));
353	        grid->Add(cell, 0);
354	    }
355	    auto* plus = new ColourCell(panel, self->m_theme, palette, wxColour(), false, [self, view] {
356	        pick_colour(self, view.slot.value_or(0), view);
357	    });
358	    plus->SetName("Other colour");
359	    plus->SetToolTip(_L("Other colour…"));
360	    grid->Add(plus, 0);
361	    column->Add(grid, 0);
362	
363	    panel->SetSizerAndFit(column);
364	    return panel;
365	}
366	
367	void FilamentMenu::pick_colour(const Ptr& self, std::size_t slot, View back)
368	{
369	    // The system picker is modal, and on macOS its window frame is its only
370	    // way out -- a transient popup above it would cover that frame. The popup
371	    // goes first and comes back afterwards.
372	    if (auto* menu = self->m_menu.get()) menu->close();
373	    const auto slots = SetupCommands::filament_slots();
374	    wxColourData data;
375	    data.SetChooseFull(true);
376	    if (slot < slots.size()) data.SetColour(wxColour(slots[slot].colour));
377	    const auto saved = SetupCommands::saved_colours();
378	    for (std::size_t i = 0; i < saved.size() && i < 16; ++i)
379	        data.SetCustomColour(int(i), saved[i]);
380	    wxColourDialog dialog(self->m_owner, &data);
381	    dialog.CenterOnParent();
382	    if (dialog.ShowModal() == wxID_OK) {
383	        const wxColour picked = dialog.GetColourData().GetColour();
384	        SetupCommands::remember_colour(picked);
385	        if (self->m_host.plater) SetupCommands::set_filament_colour(*self->m_host.plater, slot, picked);
386	        if (self->m_host.changed) self->m_host.changed();
387	    }
388	    reopen(self, back);
389	}
390	
391	} // namespace Slic3r::GUI::JusPrin
